# نمط Observer (المراقب)

## الفكرة الأساسية

```
┌─────────────────────────────────────────────────────────┐
│                    Subject (الموضوع)                     │
│  ┌─────────────────────────────────────────────────┐   │
│  │  + subscribe(observer)                          │   │
│  │  + unsubscribe(observer)                        │   │
│  │  + notify()                                     │   │
│  └─────────────────────────────────────────────────┘   │
│                         │                               │
│            ┌────────────┼────────────┐                  │
│            ▼            ▼            ▼                  │
│      ┌──────────┐ ┌──────────┐ ┌──────────┐           │
│      │Observer 1│ │Observer 2│ │Observer 3│           │
│      └──────────┘ └──────────┘ └──────────┘           │
│                                                         │
│   عندما يتغير Subject → يتصل بـ notify() →            │
│   جميع المراقبين يتم إخطارهم تلقائياً                  │
└─────────────────────────────────────────────────────────┘
```

## مثال عملي: نظام إشعارات متجر إلكتروني

```typescript
// ============================================
// الواجهة الأساسية للمراقب
// ============================================
interface Observer {
  update(data: unknown): void;
}

// ============================================
// واجهة الموضوع (Subject)
// ============================================
interface Subject {
  subscribe(observer: Observer): void;
  unsubscribe(observer: Observer): void;
  notify(): void;
}

// ============================================
// المنتج (الموضوع الذي نراقبه)
// ============================================
class Product implements Subject {
  private observers: Observer[] = [];
  private stock: number = 0;
  private name: string;

  constructor(name: string, initialStock: number) {
    this.name = name;
    this.stock = initialStock;
  }

